function n_add(x, y) { return x + y; };
exports.n_add = n_add;
function n_multiply(x, y) { const r = x * y; return [r, 1 / r]; };
exports.n_multiply = n_multiply;
function n_bits(x) { return [x | 0, x >>> 0, ~x, x << 1]; };
exports.n_bits = n_bits;
function n_compare(x, y) { return [x < y, x <= y, x === y, x == y]; };
exports.n_compare = n_compare;
function n_index(x) { return ["zero", "one", "two"][x]; };
exports.n_index = n_index;
function n_increment(x) { x++; return x; };
exports.n_increment = n_increment;
function n_negate(x) { return [-x, +x, 1 / -x]; };
exports.n_negate = n_negate;
function n_fixed(x) { return x.toFixed(1); };
exports.n_fixed = n_fixed;
function n_math(x) { return [Math.floor(x), Math.abs(x), Math.max(x, 1)]; };
exports.n_math = n_math;
function n_loop(x) { let n = 0; for (let i = 0; i < x && i < 50; i++) n += i; return n; };
exports.n_loop = n_loop;
function n_literal(x) { return x === 1 ? "one" : x === 2 ? "two" : "other"; };
exports.n_literal = n_literal;
function b_not(x) { return [!x, x === true, x === false, x ? 1 : 2, x & 1]; };
exports.b_not = b_not;
function b_true(x) { return x === true ? "true" : "not true"; };
exports.b_true = b_true;
function big_add(x) { return x + 1n; };
exports.big_add = big_add;
function sym_text(x) { return x.description; };
exports.sym_text = sym_text;
function nil_only(x, y) { return [x === null, y === undefined, x ?? "was nil", y ?? "was nil"]; };
exports.nil_only = nil_only;
